assertions_source:
// Velocity Labs directory integrity; human fields are group-scoped.
people attribute "uid" present;
people attribute "cn" present;
group "BenchmarkOperators" members >= 2;
people in "BenchmarkOperators" attribute "mail" present;
people in "BenchmarkOperators" attribute "title" present;
people in "BenchmarkOperators" attribute "ou" == "Performance";
